#pragma once

// The one place the printer/spool chip reads and changes Orca's machine and
// material setup.
//
// Every function here either reads the preset bundle or calls an existing
// public Orca entry point. Nothing writes a preset or a colour into the config
// on its own, because doing that skips the dirty tracking, the undo snapshot,
// the compatibility pass, and the background-process invalidation that the
// sidebar's own path performs.
//
// Collected in one file rather than spread across the chip and its two menus
// so the comments naming each upstream reference sequence exist once, and a
// future rebase has one place to check when those sequences move.

#include "libslic3r/Preset.hpp"

#include <wx/colour.h>
#include <wx/string.h>

#include <string>
#include <vector>

namespace Slic3r::GUI { class Plater; }

namespace Slic3r::GUI::JusPrin::SetupCommands {

struct PrinterInfo
{
    std::string preset_name;
    wxString    nickname;        // printer_model, else the label without " nozzle"
    double      nozzle{0.};
    std::size_t extruder_count{1};
    bool        valid{false};
};

struct FilamentInfo
{
    std::string preset_name;
    wxString    alias;           // display name, "@printer" suffix removed
    wxString    vendor;
    wxString    material;        // filament_type[0], e.g. "PLA"
    bool        valid{false};
};

// -- Reads ------------------------------------------------------------------

PrinterInfo  current_printer();
FilamentInfo current_filament();          // extruder 0
// The project's extruder-0 filament colour as "#RRGGBB", or empty.
wxString     current_colour();

struct NozzleVariant
{
    std::string preset_name;
    double      nozzle{0.};
    bool        current{false};
};
// Sibling printer presets for the same printer model that differ only in
// nozzle, smallest first.
std::vector<NozzleVariant> nozzle_variants();

struct BedTypeChoice
{
    int      value{0};           // BedType enum value
    wxString label;
    bool     current{false};
};
// The bed types this printer offers, as Orca's own sidebar list reports them.
// Empty when the printer does not support a bed-type choice.
std::vector<BedTypeChoice> bed_types();

// Filament presets that are visible and compatible with the current printer.
// Uses the same is_compatible flag Orca's sidebar filters on; the compatibility
// rule itself is never re-derived here.
std::vector<FilamentInfo> compatible_filaments();

enum class ConnectionState
{
    NotConnected, // no network printer, or a host Orca does not report state for
    Idle,
    Printing,
    Offline
};

struct PrinterConnection
{
    ConnectionState state{ConnectionState::NotConnected};
    // Whether the monitor tab has a machine to show.
    bool            monitor_available{false};
};
PrinterConnection printer_connection();

// -- Writes -----------------------------------------------------------------

// Switches the extruder-0 filament preset. Mirrors the filament branch of the
// private Plater::priv::on_select_preset, minus the sidebar combo's own
// presentation. Returns false when the preset does not exist.
bool select_filament_preset(Plater& plater, const std::string& preset_name);

// Sets the extruder-0 filament colour. Mirrors PlaterPresetComboBox::
// sync_colour_config, minus the combo's own repaint.
void set_filament_colour(Plater& plater, const wxColour& colour);

// Switches the printer preset. Mirrors the printer branch of
// Plater::priv::on_select_preset through Plater's public
// update_objects_position_when_select_preset.
bool select_printer_preset(Plater& plater, const std::string& preset_name);

// Applies a bed type through Sidebar::set_bed_type_accord_combox, the public
// method Orca itself uses; it notifies the combo, so Orca's own handler owns
// the app-config write, the slice invalidation, and the re-render.
bool select_bed_type(Plater& plater, int bed_type_value);

// Opens an Orca settings tab, exactly as PlaterPresetComboBox::switch_to_tab.
void open_settings_tab(Preset::Type type);
// Orca's own "Import Configs" flow, dialogs included.
void import_preset_file();
// The monitor tab, when a machine is connected.
void open_monitor();

// -- Naming -----------------------------------------------------------------

// The plain-language colour word for a hex value ("Cold White", "Red"), used
// to prefill a new spool's name. Empty when no word is close enough.
wxString colour_word(const wxColour& colour);

// The twelve-swatch palette the "new spool" step offers, in Figma's order.
struct Swatch { const char* hex; const char* name; };
const std::vector<Swatch>& swatches();

} // namespace Slic3r::GUI::JusPrin::SetupCommands

#include "SetupCommands.hpp"

#include "libslic3r/PresetBundle.hpp"
#include "libslic3r/PrintConfig.hpp"
#include "slic3r/GUI/DeviceCore/DevManager.h"
#include "slic3r/GUI/DeviceManager.hpp"
#include "slic3r/GUI/Event.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/I18N.hpp"
#include "slic3r/GUI/MainFrame.hpp"
#include "slic3r/GUI/ParamsDialog.hpp"
#include "slic3r/GUI/Plater.hpp"
#include "slic3r/GUI/Tab.hpp"

#include <algorithm>
#include <cmath>

namespace Slic3r::GUI::JusPrin::SetupCommands {

namespace {

// The alias Orca shows in the sidebar: the preset's alias, with the
// "@<printer>" qualifier trimmed the way StatusRow already trims it.
wxString display_alias(const Preset& preset)
{
    wxString alias = wxString::FromUTF8(preset.alias.empty() ? preset.name : preset.alias);
    alias = alias.BeforeFirst('@');
    alias.Trim();
    return alias;
}

wxString option_string(const DynamicPrintConfig& config, const char* key, unsigned index = 0)
{
    if (const auto* option = config.option<ConfigOptionStrings>(key); option && option->values.size() > index)
        return wxString::FromUTF8(option->values[index]);
    return {};
}

} // namespace

PrinterInfo current_printer()
{
    PrinterInfo info;
    const PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr)
        return info;
    const Preset& printer = presets->printers.get_edited_preset();
    info.preset_name = printer.name;
    info.nickname    = wxString::FromUTF8(printer.config.opt_string("printer_model"));
    if (info.nickname.empty()) {
        info.nickname = wxString::FromUTF8(printer.label(false));
        // Custom profiles often encode the nozzle in their display name.
        const auto nozzle_suffix = info.nickname.Find(" nozzle");
        if (nozzle_suffix != wxNOT_FOUND) info.nickname = info.nickname.Left(nozzle_suffix).BeforeLast(' ');
    }
    if (const auto* nozzle = printer.config.option<ConfigOptionFloats>("nozzle_diameter"); nozzle && !nozzle->values.empty()) {
        info.nozzle         = nozzle->values.front();
        info.extruder_count = nozzle->values.size();
    }
    info.valid = true;
    return info;
}

FilamentInfo current_filament()
{
    FilamentInfo info;
    const PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr || presets->filament_presets.empty())
        return info;
    info.preset_name = presets->filament_presets.front();
    const Preset* preset = presets->filaments.find_preset(info.preset_name);
    if (preset == nullptr)
        return info;
    info.alias    = display_alias(*preset);
    info.vendor   = wxString::FromUTF8(preset->vendor != nullptr ? preset->vendor->name : std::string{});
    info.material = option_string(preset->config, "filament_type");
    info.valid    = true;
    return info;
}

wxString current_colour()
{
    const PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr)
        return {};
    return option_string(presets->project_config, "filament_colour");
}

std::vector<NozzleVariant> nozzle_variants()
{
    std::vector<NozzleVariant> variants;
    const PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr)
        return variants;
    const Preset&     edited = presets->printers.get_edited_preset();
    const std::string model  = edited.config.opt_string("printer_model");
    if (model.empty())
        return variants;

    for (const Preset& preset : presets->printers) {
        if (!preset.is_visible || preset.is_default)
            continue;
        if (preset.config.opt_string("printer_model") != model)
            continue;
        const auto* nozzle = preset.config.option<ConfigOptionFloats>("nozzle_diameter");
        if (nozzle == nullptr || nozzle->values.empty())
            continue;
        variants.push_back({preset.name, nozzle->values.front(), preset.name == edited.name});
    }
    std::sort(variants.begin(), variants.end(),
              [](const NozzleVariant& a, const NozzleVariant& b) { return a.nozzle < b.nozzle; });
    // One variant is not a choice; the row shows the value without a submenu.
    if (variants.size() < 2)
        variants.clear();
    return variants;
}

std::vector<BedTypeChoice> bed_types()
{
    std::vector<BedTypeChoice> choices;
    auto* plater = wxGetApp().plater();
    if (plater == nullptr)
        return choices;

    // Orca filters the list per printer model; read its filtered list rather
    // than enumerating the BedType enum, or the menu would offer plates this
    // machine does not have.
    const std::vector<BedType>& supported = plater->sidebar().get_cur_combox_bed_types();
    if (supported.size() < 2)
        return choices;
    const BedType current = plater->sidebar().get_cur_select_bed_type();

    const ConfigOptionDef* definition = print_config_def.get("curr_bed_type");
    for (BedType type : supported) {
        wxString label;
        if (definition != nullptr) {
            // enum_values is 0-based over the labels that follow btDefault.
            const int index = int(type) - 1;
            if (index >= 0 && index < int(definition->enum_labels.size()))
                label = _(definition->enum_labels[index]);
        }
        if (label.empty())
            label = wxString::Format("%d", int(type));
        choices.push_back({int(type), label, type == current});
    }
    return choices;
}

std::vector<FilamentInfo> compatible_filaments()
{
    std::vector<FilamentInfo> filaments;
    const PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr)
        return filaments;
    for (const Preset& preset : presets->filaments) {
        // is_compatible is maintained by PresetBundle::update_compatible; the
        // compatibility rule is never re-derived here.
        if (!preset.is_visible || !preset.is_compatible || preset.is_default)
            continue;
        FilamentInfo info;
        info.preset_name = preset.name;
        info.alias       = display_alias(preset);
        info.vendor      = wxString::FromUTF8(preset.vendor != nullptr ? preset.vendor->name : std::string{});
        info.material    = option_string(preset.config, "filament_type");
        info.valid       = true;
        filaments.push_back(std::move(info));
    }
    return filaments;
}

PrinterConnection printer_connection()
{
    PrinterConnection connection;
    const PresetBundle* presets = wxGetApp().preset_bundle;
    // Only the Bambu network path reports a live machine state. Every other
    // print host is "not connected" here, which is a statement about what
    // JusPrin can observe, not a claim about the machine.
    if (presets == nullptr || !presets->use_bbl_network())
        return connection;
    auto* devices = wxGetApp().getDeviceManager();
    if (devices == nullptr)
        return connection;
    MachineObject* machine = devices->get_selected_machine();
    if (machine == nullptr)
        return connection;
    connection.monitor_available = true;
    if (!machine->is_connected())
        connection.state = ConnectionState::Offline;
    else if (machine->is_in_printing())
        connection.state = ConnectionState::Printing;
    else
        connection.state = ConnectionState::Idle;
    return connection;
}

bool select_filament_preset(Plater& plater, const std::string& preset_name)
{
    PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr || presets->filaments.find_preset(preset_name) == nullptr)
        return false;
    Tab* tab = wxGetApp().get_tab(Preset::TYPE_FILAMENT);
    if (tab == nullptr)
        return false;

    // The sequence Plater::priv::on_select_preset runs for a filament combo,
    // without the sidebar combo's own repaint and AMS badge. There is no
    // single public Orca call for "select filament preset N by name": the only
    // entry point is a wxEVT_COMBOBOX carrying a PlaterPresetComboBox as its
    // event object, and firing that would mean driving a hidden control.
    // If upstream grows such a call, this body should become one line.
    presets->set_filament_preset(0, preset_name);
    plater.update_project_dirty_from_presets();
    presets->export_selections(*wxGetApp().app_config);
    plater.on_filament_change(0);
    tab->select_preset(preset_name);
    plater.on_config_change(presets->full_config());
    return true;
}

void set_filament_colour(Plater& plater, const wxColour& colour)
{
    PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr || !colour.IsOk())
        return;
    DynamicPrintConfig& project = presets->project_config;

    // PlaterPresetComboBox::sync_colour_config, patching extruder 0. The three
    // options move together: a colour written without its type and
    // multi-colour siblings leaves a gradient's leftovers behind.
    auto patch = [&](const char* key, const std::string& value) -> ConfigOptionStrings* {
        auto* option = static_cast<ConfigOptionStrings*>(project.option(key)->clone());
        if (option->values.empty()) option->values.resize(1);
        option->values[0] = value;
        return option;
    };
    const std::string hex = colour.GetAsString(wxC2S_HTML_SYNTAX).ToStdString();

    DynamicPrintConfig updated = project;
    updated.set_key_value("filament_multi_colour", patch("filament_multi_colour", hex));
    updated.set_key_value("filament_colour", patch("filament_colour", hex));
    updated.set_key_value("filament_colour_type", patch("filament_colour_type", "1")); // solid, not gradient
    project.apply(updated);

    plater.update_project_dirty_from_presets();
    presets->export_selections(*wxGetApp().app_config);
    plater.on_config_change(updated);

    auto* changed = new wxCommandEvent(EVT_FILAMENT_COLOR_CHANGED);
    changed->SetInt(0);
    wxQueueEvent(&plater, changed);
}

bool select_printer_preset(Plater& plater, const std::string& preset_name)
{
    PresetBundle* presets = wxGetApp().preset_bundle;
    if (presets == nullptr || presets->printers.find_preset(preset_name) == nullptr)
        return false;
    Tab* tab = wxGetApp().get_tab(Preset::TYPE_PRINTER);
    if (tab == nullptr)
        return false;
    if (presets->printers.get_edited_preset().name == preset_name)
        return true;

    // The printer branch of Plater::priv::on_select_preset. The wrapper is
    // Orca's, and it is what keeps objects on their plates when the bed shape
    // changes with the preset.
    plater.update_objects_position_when_select_preset([tab, preset_name, presets, &plater] {
        tab->select_preset(preset_name);
        plater.on_config_change(presets->full_config());
    });
    return true;
}

bool select_bed_type(Plater& plater, int bed_type_value)
{
    const std::vector<BedType>& supported = plater.sidebar().get_cur_combox_bed_types();
    const auto found = std::find(supported.begin(), supported.end(), BedType(bed_type_value));
    if (found == supported.end())
        return false;
    // set_bed_type_accord_combox selects *and notifies*, so Orca's own
    // on_select_bed_type runs: it owns the project-config write, the
    // app-config record, the invalidation of every plate still on the default
    // bed, and the re-render. None of that is repeated here.
    //
    // Ownership note: a bed type is machine state to the person and project
    // state to Orca. The chip presents it under the printer because that is
    // where the person looks for it; the value still lives in the project.
    plater.sidebar().set_bed_type_accord_combox(BedType(bed_type_value));
    return true;
}

void open_settings_tab(Preset::Type type)
{
    Tab* tab = wxGetApp().get_tab(type);
    if (tab == nullptr)
        return;
    // PlaterPresetComboBox::switch_to_tab: the Tab activates its own page and
    // ParamsPanel, including clearing the previous page.
    wxGetApp().params_dialog()->Popup();
    tab->OnActivate();
    tab->restore_last_select_item();
}

void import_preset_file()
{
    // Orca's own Import Configs entry point: file dialog, overwrite
    // confirmation, and result message all belong to it.
    if (auto* frame = wxGetApp().mainframe; frame != nullptr)
        frame->load_config_file();
}

void open_monitor()
{
    if (auto* frame = wxGetApp().mainframe; frame != nullptr)
        frame->select_tab(size_t(MainFrame::tpMonitor));
}

const std::vector<Swatch>& swatches()
{
    // The twelve-swatch grid of the "new spool" step. Values are the semantic
    // filament colours the design calls for, not UI tokens: they stand for
    // physical filament, so they do not change between light and dark.
    static const std::vector<Swatch> palette{
        {"#1A1A1A", "Black"},  {"#F5F5F0", "White"},   {"#8C8C8C", "Grey"},  {"#C0392B", "Red"},
        {"#E67E22", "Orange"}, {"#F1C40F", "Yellow"},  {"#27AE60", "Green"}, {"#16A085", "Teal"},
        {"#2E6FD9", "Blue"},   {"#8E44AD", "Purple"},  {"#E084B7", "Pink"},  {"#7F8C8D", "Multicolour"}};
    return palette;
}

wxString colour_word(const wxColour& colour)
{
    if (!colour.IsOk())
        return {};
    // Nearest swatch in plain RGB distance. This only prefills a name the
    // person can edit, so a simple metric is the honest amount of machinery.
    const Swatch* best = nullptr;
    double best_distance = 0.;
    for (const Swatch& swatch : swatches()) {
        const wxColour candidate(wxString::FromUTF8(swatch.hex));
        const double dr = colour.Red() - candidate.Red();
        const double dg = colour.Green() - candidate.Green();
        const double db = colour.Blue() - candidate.Blue();
        const double distance = dr * dr + dg * dg + db * db;
        if (best == nullptr || distance < best_distance) {
            best          = &swatch;
            best_distance = distance;
        }
    }
    // Roughly a quarter of the diagonal of the RGB cube: past that, no word
    // describes the colour better than none.
    constexpr double kTooFar = 110. * 110. * 3.;
    if (best == nullptr || best_distance > kTooFar)
        return {};
    return _(best->name);
}

} // namespace Slic3r::GUI::JusPrin::SetupCommands

#pragma once

// The Prepare header's machine chip: printer on the left, spool on the right,
// one outline around both.
//
// The halves are two HeaderButtons rather than one control with two hit
// regions, so each gets its own hover, pressed, focus and open state for free,
// and each can anchor its own menu. Left and right arrow keys move between
// them, so the chip behaves like one control to the keyboard while remaining
// two to the pointer.
//
// The chip renders state and raises intent. It reads nothing from the spool
// store and changes nothing in Orca; StatusRow owns both.

#include "HeaderControls.hpp"

#include <wx/panel.h>
#include <wx/string.h>

#include <functional>

namespace Slic3r::GUI::JusPrin {

class PrinterSpoolChip : public wxPanel
{
public:
    PrinterSpoolChip(wxWindow* parent, const ShellTheme& theme);

    // Left half. `nozzle` is already formatted for display.
    void set_printer(const wxString& nickname, const wxString& nozzle);
    // Right half. An invalid colour draws the dashed "no spool" ring.
    void set_spool(const wxString& name, const wxColour& colour);

    void set_dark(bool dark);

    // Raised when a half is activated, by pointer or keyboard.
    void on_printer_activated(std::function<void()> handler) { m_printer_activated = std::move(handler); }
    void on_spool_activated(std::function<void()> handler) { m_spool_activated = std::move(handler); }

    HeaderButton& printer_half() { return *m_printer; }
    HeaderButton& spool_half() { return *m_spool; }

    wxSize DoGetBestSize() const override;

private:
    void layout();

    HeaderButton* m_printer{nullptr};
    HeaderButton* m_spool{nullptr};
    std::function<void()> m_printer_activated;
    std::function<void()> m_spool_activated;
};

} // namespace Slic3r::GUI::JusPrin

#include "PrinterSpoolChip.hpp"

#include "slic3r/GUI/I18N.hpp"

#include <wx/sizer.h>

namespace Slic3r::GUI::JusPrin {

namespace {
// Neither half may grow past this, so one long preset name cannot push the
// print action off the row. The full text stays available in the tooltip.
constexpr int kHalfLabelCapDip = 240;
} // namespace

PrinterSpoolChip::PrinterSpoolChip(wxWindow* parent, const ShellTheme& theme)
    : wxPanel(parent, wxID_ANY)
{
    SetName("Printer and spool");
    // The halves paint edge to edge; the panel itself is never visible.
    SetBackgroundStyle(wxBG_STYLE_PAINT);
    Bind(wxEVT_PAINT, [](wxPaintEvent&) {});

    m_printer = new HeaderButton(this, theme, HeaderStyle::ChipLeft, wxEmptyString, HeaderIcon::Machine);
    m_printer->SetName("Printer");
    m_printer->set_label_cap(kHalfLabelCapDip);
    m_spool = new HeaderButton(this, theme, HeaderStyle::ChipRight, wxEmptyString, HeaderIcon::None);
    m_spool->SetName("Spool");
    m_spool->set_label_cap(kHalfLabelCapDip);

    m_printer->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_printer_activated) m_printer_activated(); });
    m_spool->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_spool_activated) m_spool_activated(); });

    // Left and right move between the halves; the halves themselves keep
    // Return and Space, which HeaderButton already handles.
    auto arrows = [this](HeaderButton* self, HeaderButton* other) {
        self->Bind(wxEVT_KEY_DOWN, [self, other](wxKeyEvent& event) {
            const int key = event.GetKeyCode();
            if (key == WXK_LEFT || key == WXK_RIGHT) {
                if (self != other) other->SetFocus();
                return;
            }
            event.Skip();
        });
    };
    arrows(m_printer, m_spool);
    arrows(m_spool, m_printer);

    Bind(wxEVT_SIZE, [this](wxSizeEvent& event) { layout(); event.Skip(); });
}

void PrinterSpoolChip::set_printer(const wxString& nickname, const wxString& nozzle)
{
    const wxString name = nickname.empty() ? _L("Select printer") : nickname;
    m_printer->SetLabel(name);
    HeaderRowDecoration decoration;
    // The nozzle is a measurement, so it takes the teletype face.
    decoration.detail    = nozzle;
    decoration.technical = true;
    decoration.trailing  = HeaderIcon::Down;
    m_printer->set_decoration(std::move(decoration));
    // The tooltip carries the full text the chip may have ellipsized. It says
    // what is selected and nothing about whether it is loaded: the chip makes
    // no claim about the physical machine.
    m_printer->SetToolTip(nozzle.empty() ? name : name + wxString::FromUTF8(" \xC2\xB7 ") + nozzle + " mm");
    InvalidateBestSize();
    layout();
}

void PrinterSpoolChip::set_spool(const wxString& name, const wxColour& colour)
{
    const wxString label = name.empty() ? _L("Select spool") : name;
    m_spool->SetLabel(label);
    HeaderRowDecoration decoration;
    decoration.dot      = colour; // an invalid colour draws the dashed ring
    decoration.trailing = HeaderIcon::Down;
    m_spool->set_decoration(std::move(decoration));
    m_spool->SetToolTip(label);
    InvalidateBestSize();
    layout();
}

void PrinterSpoolChip::set_dark(bool dark)
{
    m_printer->set_dark(dark);
    m_spool->set_dark(dark);
    Refresh();
}

wxSize PrinterSpoolChip::DoGetBestSize() const
{
    const wxSize left = m_printer->GetBestSize(), right = m_spool->GetBestSize();
    return {left.x + right.x, std::max(left.y, right.y)};
}

void PrinterSpoolChip::layout()
{
    const wxSize size = GetClientSize();
    if (size.x <= 0) return;
    // Under pressure both halves give up width in proportion to what they
    // asked for, so neither collapses to its ellipsis while the other keeps
    // slack.
    const int wanted_left  = m_printer->GetBestSize().x;
    const int wanted_right = m_spool->GetBestSize().x;
    const int wanted       = wanted_left + wanted_right;
    const int left = wanted <= size.x || wanted == 0 ? wanted_left : size.x * wanted_left / wanted;
    m_printer->SetSize(0, 0, left, size.y);
    m_spool->SetSize(left, 0, size.x - left, size.y);
}

} // namespace Slic3r::GUI::JusPrin

