// The chip's left-half menu: what this printer is, what it is doing, and the
// two setup values a person changes often enough to want here -- nozzle and
// plate. Everything else is a door into Orca's own settings.
//
// Five rows for one printer, by design. Listing several printers, adding one,
// and connecting a non-Bambu host are separate work; this slice shows one
// machine and says plainly when it cannot see its state.

#include "HeaderControls.hpp"

#include <functional>

namespace Slic3r::GUI { class Plater; }

namespace Slic3r::GUI::JusPrin {

class PrinterMenu
{
public:
    // Builds and opens the menu anchored to the chip's left half. The menu
    // destroys itself on dismissal, as HeaderMenu already does.
    static void open(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor);

private:
    static std::vector<HeaderMenuItem> rows(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater,
                                            HeaderButton& anchor);
};

} // namespace Slic3r::GUI::JusPrin

#include "PrinterMenu.hpp"
#include "SetupCommands.hpp"

#include "slic3r/GUI/I18N.hpp"
#include "slic3r/GUI/Plater.hpp"

#include <wx/weakref.h>

namespace Slic3r::GUI::JusPrin {

namespace {

wxString nozzle_text(double nozzle) { return wxString::Format("%g mm", nozzle); }

// A sub-list replaces the menu's own rows rather than opening a second popup:
// the person stays in one surface, and Escape still means "close the menu".
void show_sublist(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor,
                  HeaderMenu& menu, const wxString& title, std::vector<HeaderMenuItem> choices);

std::vector<HeaderMenuItem> nozzle_rows(wxWindow* owner, Plater& plater)
{
    std::vector<HeaderMenuItem> rows;
    for (const auto& variant : SetupCommands::nozzle_variants()) {
        HeaderMenuItem row;
        row.label                 = nozzle_text(variant.nozzle);
        row.decoration.check      = variant.current;
        row.decoration.technical  = true;
        row.invoke = [owner = wxWeakRef<wxWindow>(owner), &plater, name = variant.preset_name] {
            if (owner) SetupCommands::select_printer_preset(plater, name);
        };
        rows.push_back(std::move(row));
    }
    return rows;
}

std::vector<HeaderMenuItem> plate_rows(wxWindow* owner, Plater& plater)
{
    std::vector<HeaderMenuItem> rows;
    for (const auto& choice : SetupCommands::bed_types()) {
        HeaderMenuItem row;
        row.label            = choice.label;
        row.decoration.check = choice.current;
        row.invoke = [owner = wxWeakRef<wxWindow>(owner), &plater, value = choice.value] {
            if (owner) SetupCommands::select_bed_type(plater, value);
        };
        rows.push_back(std::move(row));
    }
    return rows;
}

void show_sublist(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor,
                  HeaderMenu& menu, const wxString& title, std::vector<HeaderMenuItem> choices)
{
    std::vector<HeaderMenuItem> rows;
    HeaderMenuItem back;
    back.label          = title;
    back.icon           = HeaderIcon::Back;
    back.invoke         = {}; // filled below, once the menu pointer is captured
    rows.push_back(std::move(back));
    rows.back().invoke = [owner = wxWeakRef<wxWindow>(owner), &theme, dark, &plater, anchor = wxWeakRef<HeaderButton>(&anchor),
                          menu = wxWeakRef<wxWindow>(&menu)] {
        // Going back rebuilds the top level in the same popup.
        if (owner && anchor && menu)
            static_cast<HeaderMenu*>(menu.get())->replace_items({});
    };
    rows.push_back({wxEmptyString, HeaderIcon::None, {}, true, true, {}, false, {}});
    for (auto& choice : choices) rows.push_back(std::move(choice));
    menu.replace_items(std::move(rows));
}

} // namespace

std::vector<HeaderMenuItem> PrinterMenu::rows(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater,
                                              HeaderButton& anchor)
{
    const auto printer    = SetupCommands::current_printer();
    const auto connection = SetupCommands::printer_connection();
    std::vector<HeaderMenuItem> rows;

    // Row 1: the machine and what it is doing. A state the product cannot
    // observe is reported as "Not connected" with a plain explanation, never
    // as a guess or a warning colour.
    HeaderMenuItem machine;
    machine.label             = printer.nickname.empty() ? _L("No printer selected") : printer.nickname;
    machine.decoration.bold   = true;
    machine.enabled           = connection.monitor_available;
    switch (connection.state) {
    case SetupCommands::ConnectionState::Idle:
        machine.decoration.status = StatusTone::Positive;
        machine.decoration.status_word = _L("Idle");
        machine.decoration.trailing = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Printing:
        machine.decoration.status = StatusTone::Busy;
        machine.decoration.status_word = _L("Printing");
        machine.decoration.trailing = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Offline:
        machine.decoration.status = StatusTone::Neutral;
        machine.decoration.status_word = _L("Offline");
        machine.decoration.trailing = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::NotConnected:
        machine.decoration.status = StatusTone::Neutral;
        machine.decoration.status_word = _L("Not connected");
        // Connect… is deferred, so the sub-line states the consequence rather
        // than offering an action that does nothing.
        machine.decoration.sub_label = _L("Prints go to a card.");
        break;
    }
    if (connection.monitor_available)
        machine.invoke = [] { SetupCommands::open_monitor(); };
    rows.push_back(std::move(machine));

    // Nozzle and plate: the two setup values worth changing from here.
    HeaderMenuItem nozzle;
    nozzle.label                = _L("Nozzle");
    nozzle.separator            = true;
    nozzle.decoration.detail    = nozzle_text(printer.nozzle);
    nozzle.decoration.technical = true;
    auto variants = SetupCommands::nozzle_variants();
    nozzle.enabled = !variants.empty();
    if (nozzle.enabled) {
        nozzle.decoration.trailing = HeaderIcon::Right;
        nozzle.invoke = {}; // set by open(), which owns the menu pointer
    }
    rows.push_back(std::move(nozzle));

    HeaderMenuItem plate;
    plate.label = _L("Plate");
    auto plates = SetupCommands::bed_types();
    for (const auto& choice : plates)
        if (choice.current) plate.decoration.detail = choice.label;
    plate.enabled = !plates.empty();
    if (plate.enabled)
        plate.decoration.trailing = HeaderIcon::Right;
    rows.push_back(std::move(plate));

    HeaderMenuItem settings;
    settings.label     = _L("Printer settings…");
    settings.separator = true;
    settings.invoke    = [] { SetupCommands::open_settings_tab(Preset::TYPE_PRINTER); };
    rows.push_back(std::move(settings));

    HeaderMenuItem add;
    add.label  = _L("Add a printer…");
    add.invoke = [] { wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS); };
    rows.push_back(std::move(add));

    return rows;
}

void PrinterMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor)
{
    auto* menu = new HeaderMenu(owner, theme, dark, rows(owner, theme, dark, plater, anchor));
    menu->open(anchor);
}

} // namespace Slic3r::GUI::JusPrin

