static wxEvtHandler * HitTest(wxWindow * parent, wxMouseEvent &evt)
{
    auto pt = evt.GetPosition();
    const wxWindowList &children = parent->GetChildren();
    for (auto w : children) {
        wxRect rc { w->GetPosition(), w->GetSize() };
        if (rc.Contains(pt)) {
            evt.SetPosition(pt - rc.GetTopLeft());
            if (auto child = HitTest(w, evt))
                return child;
            return w;
        }
    }
    return nullptr;
}

void PopupWindow::OnMouseEvent2(wxMouseEvent &evt)
{
    auto child = ::HitTest(this, evt);
    if (evt.GetEventType() == wxEVT_MOTION) {
        auto h = child ? child : this;
        if (hovered != h) {
            wxMouseEvent leave(wxEVT_LEAVE_WINDOW);
            leave.SetEventObject(hovered);
            leave.SetId(static_cast<wxWindow*>(hovered)->GetId());
            hovered->ProcessEventLocally(leave);
            hovered = h;
            wxMouseEvent enter(wxEVT_ENTER_WINDOW);
            enter.SetEventObject(hovered);
            enter.SetId(static_cast<wxWindow*>(hovered)->GetId());
            hovered->ProcessEventLocally(enter);
        }
    }
    if (child) {
        child->ProcessEventLocally(evt);
    } else {
        evt.Skip();
    }

void choose_header_item(const wxString& name, std::function<void()> then)
{
    auto* menu = visible_header_menu();
    auto* item = menu ? wxWindow::FindWindowByName(name,menu) : nullptr;
    if (!item || !item->IsEnabled()) throw std::runtime_error("missing enabled header menu item: " + name.ToStdString());
    for (size_t i=0;i<menu->GetChildren().size() && menu->selected_item() != item;++i) {
        wxKeyEvent down(wxEVT_CHAR); down.m_keyCode = WXK_DOWN;
        menu->GetEventHandler()->ProcessEvent(down);
    }
    check(menu->selected_item() == item,"header_menu_keyboard_selects_enabled_row");
    wxKeyEvent enter(wxEVT_CHAR); enter.m_keyCode = WXK_RETURN;
    menu->GetEventHandler()->ProcessEvent(enter);
    then();
}

